const messages: Record<Locale, Record<string, string>> = { zh, en };
const locale = ref<Locale>(readStoredLocale());

function readStoredLocale(): Locale {
  if (typeof window === 'undefined') return 'zh';
  try {
    const value = window.localStorage.getItem(storageKey);
    return isLocale(value) ? value : 'zh';
  } catch {
    return 'zh';
  }
}

function isLocale(value: string | null): value is Locale { return value !== null && supportedLocales.includes(value as Locale); }

function interpolate(value: string, params?: Record<string, string | number>): string {
  if (!params) return value;
  return value.replace(/\{(\w+)\}/g, (match, key: string) => params[key] === undefined ? match : String(params[key]));
}

export function t(key: string, params?: Record<string, string | number>): string {
  const value = messages[locale.value][key] ?? messages.en[key];
  if (!value) {
    if (import.meta.env.DEV) console.warn(`[i18n] Missing translation: ${key}`);
    return key;
  }
  return interpolate(value, params);
}

export function setLocale(next: Locale): void {
  locale.value = next;
  if (typeof document !== 'undefined') document.documentElement.lang = next === 'zh' ? 'zh-CN' : 'en';
  if (typeof window !== 'undefined') {
    try { window.localStorage.setItem(storageKey, next); } catch { /* Storage is optional. */ }
  }
}

if (typeof document !== 'undefined') document.documentElement.lang = locale.value === 'zh' ? 'zh-CN' : 'en';

export function useLocale() {
  return { locale: computed(() => locale.value), setLocale, t };
}

export function getLocale(): Locale { return locale.value; }
